const fs = await import("node:fs");
const p = "AUDIT_LEDGER.md";
console.log("exists", fs.existsSync(p), "bytes", fs.existsSync(p) ? fs.statSync(p).size : 0);
if (fs.existsSync(p)) {
  const txt = fs.readFileSync(p, "utf8");
  const lines = txt.split(/\r?\n/);
  console.log("lines", lines.length);
  console.log(lines.slice(-40).join("\n"));
}
", "description": "Inspect audit ledger tail"}

